const queryClient = new QueryClient();
type CartLine = { product: Product; options: string[]; quantity: number; instructions: string };
const CART_KEY = 'bpj-cart-v1';
const currency = (value?: number | null) => value == null ? '—' : new Intl.NumberFormat('en-UG', { style: 'currency', currency: 'UGX', maximumFractionDigits: 0 }).format(value);
const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ');
function readCart(): CartLine[] { try { return JSON.parse(localStorage.getItem(CART_KEY) || '[]') as CartLine[]; } catch { return []; } }
function saveCart(lines: CartLine[]) { localStorage.setItem(CART_KEY, JSON.stringify(lines)); window.dispatchEvent(new Event('cart-change')); }

function Button({ children, className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement>) {
  return <button {...props} className={cx('inline-flex items-center justify-center gap-2 rounded-full px-5 py-3 text-sm font-semibold transition duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary disabled:cursor-not-allowed disabled:opacity-50', className)}>{children}</button>;
}
