      <div className="mt-auto rounded-2xl border border-[#5b473d] bg-[#392b25] p-4"><p className="text-xs text-[#d4c3b4]">Staff workspace</p><p className="mt-1 text-sm font-semibold">Sign in with Clerk</p><Link href="/sign-in" className="mt-3 inline-flex text-xs text-[#f0a18e]" data-testid="link-staff-signin">Open staff sign in <ArrowRight size={13}/></Link></div>
