function Loading({ label = 'Getting things ready' }: { label?: string }) { return <div className="grid min-h-56 place-items-center rounded-3xl border border-dashed border-[#d9cebf] bg-[#f8f4eb] p-8 text-center" data-testid="status-loading"><div><span className="mx-auto mb-4 block h-8 w-8 animate-pulse rounded-full bg-[#e8c9bb]"/><p className="text-sm text-muted-foreground">{label}</p></div></div>; }
function QueryIssue({ retry, message = 'We could not load this just now.' }: { retry: () => void; message?: string }) { return <div className="rounded-2xl border border-[#e7c5b7] bg-[#fff6f0] p-6" role="alert" data-testid="status-error"><p className="font-semibold">{message}</p><Button className="mt-4 bg-[#30231e] text-white" onClick={retry} data-testid="button-retry">Try again</Button></div>; }
function PageTitle({ eyebrow, title, body }: { eyebrow: string; title: string; body?: string }) { return <div className="mb-8"><p className="mb-2 text-[11px] font-bold uppercase tracking-[.2em] text-primary">{eyebrow}</p><h1 className="serif text-4xl font-semibold tracking-tight md:text-5xl">{title}</h1>{body && <p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{body}</p>}</div>; }

